    first = {}
    for c in Cursus.objects.order_by("ordre", "id"):
        first.setdefault(c.etablissement_id, c.pk)
    for name in ['Level', 'Serie', 'Subject', 'SchoolClass', 'Coefficient', 'Term', 'SchoolSettings']:
        M = apps.get_model("academics", name)
        for etab_id, cursus_id in first.items():
            M.objects.filter(etablissement_id=etab_id, cursus__isnull=True).update(cursus_id=cursus_id)


